import {escapeHtml as esc,icon} from './components.js';
import {watchButton} from './watch-button.js';
import {screenMetrics,screenerGroups,screenerSorts,screenerIndices,screenerSectors,screenerPresets} from './screener-config.js';
const nf=new Intl.NumberFormat('en-US',{maximumFractionDigits:2}),compact=new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2});
const number=n=>Number.isFinite(n)?nf.format(n):'—',pct=n=>Number.isFinite(n)?(n>0?'+':'')+number(n)+'%':'—',tone=n=>n>0?'screen-up':n<0?'screen-down':'';
const labels={q:'검색',index:'지수',sector:'섹터',industry:'산업',country:'기업 소재국',type:'상품 유형'},types={all:'전체 상품',excludeEtf:'ETF 제외 · 유형 확인 종목',etf:'ETF만'};
const metricKeys=screenMetrics.flatMap(d=>[d.key+'Min',d.key+'Max']),filterKeys=[...Object.keys(labels),...metricKeys];
const timestamp=at=>at?new Date(at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',hour12:false})+' KST':'갱신 이력 없음';
export function mountScreener(root){
 let loadedQuery=null;
 let params=new URLSearchParams(location.search),controller,timer,version=0,destroyed=false,data=null,view='overview';
 root.innerHTML=`<div class="page-heading"><div><div class="eyebrow">STOCK SCREENER</div><h1>미국 종목 스크리너</h1><p class="screen-intro">조건으로 찾고, 숫자로 비교하세요.</p></div><span class="screen-source">Finviz Elite</span></div>
 <section class="surface screen-controls" aria-label="종목 검색 조건"><form id="screen-form">
 <div class="screen-search-row"><label class="screen-search">${icon('search')}<input name="q" type="search" maxlength="100" placeholder="종목명 또는 티커 검색" aria-label="스크리너 종목명 또는 티커 검색" autocomplete="off"></label><button class="primary-button" type="submit">조건 적용</button><button class="secondary-button" type="button" data-screen="reset">초기화</button></div>
 <div class="screen-presets" aria-label="빠른 조건">${screenerPresets.map((p,i)=>`<button type="button" data-screen="preset" data-preset="${i}" title="${esc(p.description)}">${esc(p.label)}</button>`).join('')}</div>
 <div class="screen-basic">${['index','sector','industry','country','type'].map(k=>`<label>${labels[k]}<select name="${k}" aria-label="${labels[k]}"></select></label>`).join('')}</div>
 <details class="screen-advanced"><summary>상세 조건 <span>시가총액 · 밸류에이션 · 성장 · 기술 지표</span></summary><div class="screen-range-groups">${Object.entries(screenerGroups).map(([group,title])=>`<fieldset><legend>${title}</legend><div class="screen-range-grid">${screenMetrics.filter(d=>d.group===group).map(d=>`<div class="screen-range"><span>${d.label}<small>${d.unit}</small></span><div>${['Min','Max'].map((suffix,i)=>`${i?'<span>~</span>':''}<input type="number" step="any" name="${d.key+suffix}" aria-label="${d.label} ${i?'최대':'최소'}${d.unit?' ('+d.unit+')':''}" placeholder="${i?'최대':'최소'}" ${d.floor!==undefined?'min="'+d.floor+'"':''} ${d.ceiling!==undefined?'max="'+d.ceiling+'"':''}>`).join('')}</div></div>`).join('')}</div></fieldset>`).join('')}</div><div class="screen-apply"><span>조건은 모두 함께 적용됩니다. 값이 없는 종목은 해당 숫자 조건에서 제외합니다.</span><button class="primary-button" type="submit">조건 적용</button></div></details>
 <p class="screen-validation" role="alert" hidden></p></form><div class="screen-chips" aria-label="적용 중인 조건"></div></section>
 <section class="surface screen-results" aria-labelledby="screen-result-title"><div class="screen-result-toolbar"><div><h2 id="screen-result-title">종목을 확인하고 있어요</h2><p class="screen-coverage"></p></div><div class="screen-sort"><label><span class="sr-only">정렬 기준</span><select data-screen="sort">${Object.entries(screenerSorts).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><select data-screen="dir" aria-label="정렬 방향"><option value="desc">내림차순</option><option value="asc">오름차순</option></select><button class="icon-button" data-screen="refresh" aria-label="스크리너 새로고침">${icon('refresh')}</button></div></div>
 <div class="screen-view" role="group" aria-label="표에 표시할 지표">${[['overview','주요 지표'],['fundamental','재무'],['technical','가격·기술']].map(([id,name])=>`<button data-screen="view" data-view="${id}" aria-pressed="${id===view}">${name}</button>`).join('')}</div>
 <p class="screen-notice" role="status" hidden></p><div class="screen-table-wrap" tabindex="0" role="region" aria-label="검색 결과 · 좌우로 스크롤"><table class="screen-table"><caption class="sr-only">Finviz 조건 검색 결과</caption><thead></thead><tbody></tbody></table></div><div class="screen-state" role="status"></div>
 <div class="screen-pagination"><label>페이지당 <select data-screen="pageSize" aria-label="페이지당 종목 수"><option>25</option><option selected>50</option><option>100</option></select>개</label><div><button class="secondary-button" data-screen="previous">이전</button><span class="screen-page-count"></span><button class="secondary-button" data-screen="next">다음</button></div></div>
 <footer class="screen-footer"><span class="screen-feed-time"></span><span>조회 스냅샷 · 거래소 시세 기준시각·지연 여부 미제공</span></footer></section>`;
 const $=s=>root.querySelector(s),form=$('#screen-form'),input=k=>form.elements.namedItem(k);
 function fillOptions(key,choices,all='전체'){
  const current=params.get(key)||'',entries=[['',all],...choices];if(current&&!entries.some(([k])=>k===current))entries.push([current,current]);
  input(key).innerHTML=entries.map(([key,value])=>`<option value="${esc(key)}">${esc(value)}</option>`).join('');input(key).value=current;
 }
 function facets(){const f=data?.facets||{};fillOptions('index',Object.entries(screenerIndices));fillOptions('sector',(f.sectors||[]).map(s=>[s,(screenerSectors[s]||s)+' · '+s]));fillOptions('country',(f.countries||[]).map(s=>[s,s]),'모든 소재국');fillOptions('type',Object.entries(types).filter(([key])=>key!=='all'),'전체 상품');fillOptions('industry',(f.industries||[]).filter(d=>!params.get('sector')||d.sector===params.get('sector')).map(d=>[d.name,d.name]));}
 function syncForm(){facets();input('q').value=params.get('q')||'';for(const key of metricKeys)input(key).value=params.get(key)||'';for(const [key,fallback]of [['sort','marketCap'],['dir','desc'],['pageSize','50']])$(`[data-screen="${key}"]`).value=params.get(key)||fallback;chips();}
 function chips(){const values=[];for(const key of Object.keys(labels)){const v=params.get(key);if(v&&!(key==='type'&&v==='all'))values.push({key,text:labels[key]+': '+(key==='type'?types[v]:key==='index'?screenerIndices[v]:key==='sector'?screenerSectors[v]||v:v)});}for(const d of screenMetrics){const min=params.get(d.key+'Min'),max=params.get(d.key+'Max');if(min||max)values.push({key:d.key,text:d.label+': '+(min&&max?min+' ~ '+max:min?min+' 이상':max+' 이하')+(d.unit?' '+d.unit:'')});}$('.screen-chips').innerHTML=values.map(x=>`<button type="button" data-screen="remove" data-key="${esc(x.key)}" aria-label="${esc(x.text)} 조건 해제">${esc(x.text)} <span aria-hidden="true">×</span></button>`).join('');}
 function commit(next,{push=true}={}){clearTimeout(timer);params=next;const url='/screener'+(params.size?'?'+params.toString():'');if(location.pathname+location.search!==url)history[push?'pushState':'replaceState']({},'',url);syncForm();load();}
 function submit(){for(const d of screenMetrics)input(d.key+'Max').setCustomValidity('');for(const d of screenMetrics){const a=input(d.key+'Min'),b=input(d.key+'Max');if(a.value!==''&&b.value!==''&&Number(a.value)>Number(b.value))b.setCustomValidity('최댓값은 최솟값 이상이어야 합니다.');}if(!form.reportValidity())return;const next=new URLSearchParams(params);for(const key of filterKeys){const value=input(key)?.value.trim();if(value)next.set(key,value);else next.delete(key);}next.delete('page');$('.screen-validation').hidden=true;commit(next);}
 async function load(){const requestQuery=params.toString(),previousData=data,retain=loadedQuery===requestQuery&&!!data;const id=++version;controller?.abort();controller=new AbortController();$('.screen-results').setAttribute('aria-busy','true');$('.screen-state').textContent='조건에 맞는 종목을 찾고 있습니다…';$('.screen-table-wrap').hidden=!retain;$('.screen-notice').hidden=true;for(const action of ['previous','next'])$(`[data-screen="${action}"]`).disabled=true;
  try{const response=await fetch('/api/screener?'+params,{signal:controller.signal});const result=await response.json();if(id!==version||destroyed)return;data=result;if(!['ready','empty'].includes(data.status))throw new Error(data.message||'스크리너 데이터 연결을 확인해 주세요.');loadedQuery=requestQuery;facets();render();}
  catch(e){if(e.name==='AbortError'||id!==version||destroyed)return;if(retain){data=previousData;render();$('.screen-state').textContent='연결 오류 · 마지막 조회 결과를 표시합니다. 상단 새로고침으로 다시 시도해 주세요.';return;}data=null;$('#screen-result-title').textContent='데이터 연결 확인 필요';$('.screen-coverage').textContent='';$('.screen-feed-time').textContent='';$('.screen-page-count').textContent='';$('.screen-state').textContent=e.message||'스크리너 조회에 실패했습니다. 새로고침을 눌러 다시 확인해 주세요.';}
  finally{if(id===version&&!destroyed)$('.screen-results').setAttribute('aria-busy','false');}
 }
 const columns={overview:[['price','현재가 · USD'],['changePct','당일'],['marketCap','시가총액 · USD'],['pe','PER'],['dividendYield','배당수익률'],['relativeVolume','상대거래량'],['rsi','RSI (14)'],['perfMonth','1개월']],fundamental:[['marketCap','시가총액 · USD'],['pe','PER'],['forwardPe','예상 PER'],['pb','PBR'],['ps','PSR'],['roe','ROE'],['profitMargin','순이익률'],['epsGrowth','EPS 증가율'],['salesGrowth','매출 증가율'],['dividendYield','배당수익률']],technical:[['price','현재가 · USD'],['changePct','당일'],['volume','거래량 · 주'],['relativeVolume','상대거래량'],['rsi','RSI (14)'],['perfWeek','1주'],['perfMonth','1개월'],['perfYear','1년'],['sma20','20일선 대비'],['sma50','50일선 대비'],['sma200','200일선 대비'],['high52','52주 최고가 대비']]};
 const percentKeys=new Set(screenMetrics.filter(d=>d.unit==='%').map(d=>d.key)),colored=new Set(['changePct','perfWeek','perfMonth','perfYear','sma20','sma50','sma200','high52']);
 function render(){if(!data)return;$('#screen-result-title').textContent='검색 결과 '+data.total.toLocaleString('ko-KR')+'개';$('.screen-coverage').textContent='Finviz 제공 '+data.universeCount.toLocaleString('ko-KR')+'개에서 검색 · 미국 상장 · 가격 USD';
  const notes=[data.stale?'갱신 지연 · 마지막 정상 데이터를 표시합니다. '+(data.message||''):'',data.typeError||'',params.get('type')&&params.get('type')!=='all'&&data.unknownTypes?'상품 유형 미확인 '+data.unknownTypes+'개는 유형 필터에서 제외합니다.':'',params.get('type')&&params.get('type')!=='all'&&data.typeStale?'ETF 분류는 마지막 저장 자료를 사용합니다.':''].filter(Boolean);$('.screen-notice').hidden=!notes.length;$('.screen-notice').textContent=notes.join(' ');$('.screen-notice').title=data.typeReceivedAt?'분류: '+data.typeSource+' · '+timestamp(data.typeReceivedAt):'';
  $('.screen-state').textContent=data.total?'':'조건에 맞는 종목이 없습니다. 조건을 줄이거나 초기화해 주세요.';$('.screen-table-wrap').hidden=!data.total;
  const cols=columns[view];$('.screen-table thead').innerHTML='<tr><th scope="col">순위</th><th scope="col"><span class="sr-only">관심종목</span></th><th scope="col">종목</th>'+cols.map(([key,label])=>`<th scope="col" ${['epsGrowth','salesGrowth'].includes(key)?'title="Finviz 제공 전년 동기 대비 분기 증가율"':''}>${Object.hasOwn(screenerSorts,key)?`<button data-screen="column" data-key="${key}">${label}${(params.get('sort')||'marketCap')===key?(params.get('dir')==='asc'?' ↑':' ↓'):''}</button>`:label}</th>`).join('')+'</tr>';
  $('.screen-table tbody').innerHTML=data.items.map(s=>`<tr><td class="screen-rank">${s.rank}</td><td>${watchButton(s)}</td><td class="screen-identity"><a href="/stock/US/${encodeURIComponent(s.ticker)}" data-nav><strong>${esc(s.ticker)}</strong><span title="${esc(s.name)}">${esc(s.name)}</span><small>${esc(screenerSectors[s.sector]||s.sector)}${s.isEtf===true?' · ETF':s.securityType==='ETN'?' · ETN':''}</small></a></td>${cols.map(([key])=>`<td class="${colored.has(key)?tone(s[key]):''}" title="${Number.isFinite(s[key])?esc(String(s[key])):'공급 데이터 없음'}">${!Number.isFinite(s[key])?'—':['marketCap','volume'].includes(key)?compact.format(s[key]):percentKeys.has(key)?pct(s[key]):number(s[key])}</td>`).join('')}</tr>`).join('');
  $('.screen-page-count').textContent=data.page+' / '+data.pages;$('[data-screen="previous"]').disabled=data.page<=1;$('[data-screen="next"]').disabled=data.page>=data.pages;$('.screen-feed-time').textContent='Finviz Elite · 서버 조회 '+timestamp(data.receivedAt);$('.screen-feed-time').title='시가총액 B=십억 USD, M=백만 USD · PER/PBR/PSR/상대거래량은 배 · EPS/매출 증가율은 전년 동기 대비';
 }
 const onSubmit=e=>{e.preventDefault();submit();};form.addEventListener('submit',onSubmit);
 const onInput=e=>{if(e.target.type==='number')for(const key of metricKeys)input(key).setCustomValidity('');if(e.target.name==='q'){clearTimeout(timer);timer=setTimeout(submit,400);}};
 const onChange=e=>{const action=e.target.dataset.screen;if(['sort','dir','pageSize'].includes(action)){const next=new URLSearchParams(params);next.set(action,e.target.value);next.delete('page');commit(next);}else if(e.target.tagName==='SELECT'&&e.target.closest('form')){if(e.target.name==='sector')input('industry').value='';submit();}};
 const onClick=e=>{const b=e.target.closest('[data-screen]');if(!b||!root.contains(b)||b.tagName!=='BUTTON')return;const action=b.dataset.screen,next=new URLSearchParams(params);
  if(action==='reset'){commit(new URLSearchParams());return;}
  if(action==='preset'){const p=screenerPresets[Number(b.dataset.preset)];if(p)commit(new URLSearchParams({...p.filters,sort:'marketCap',dir:'desc'}));return;}
  if(action==='refresh'){load();return;}if(action==='view'){view=b.dataset.view;root.querySelectorAll('[data-screen="view"]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.view===view)));render();return;}
  if(action==='remove'){const key=b.dataset.key;next.delete(key);next.delete(key+'Min');next.delete(key+'Max');if(key==='sector')next.delete('industry');next.delete('page');}
  else if(action==='previous'||action==='next'){if(!data)return;next.set('page',String(data.page+(action==='next'?1:-1)));}
  else if(action==='column'){next.set('sort',b.dataset.key);next.set('dir',params.get('sort')===b.dataset.key&&params.get('dir')!=='asc'?'asc':'desc');next.delete('page');}else return;commit(next);
 };
 root.addEventListener('input',onInput);root.addEventListener('change',onChange);root.addEventListener('click',onClick);syncForm();load();
 return {destroy(){destroyed=true;++version;controller?.abort();clearTimeout(timer);form.removeEventListener('submit',onSubmit);root.removeEventListener('input',onInput);root.removeEventListener('change',onChange);root.removeEventListener('click',onClick);}};
}
